const input = $input.first().json;
const query = (input.body?.query || input.query || '').trim();
const queryLower = query.toLowerCase();

// Section mapping: longest-match first to avoid 'ai' swallowing 'aiml b'
const sectionMap = [
  { keywords: ['sec-sk', 'sec sk', 'section sk', 'sk'], tab: 'Sec-SK', name: 'Section SK' },
  { keywords: ['software development b', 'software dev b', 'sd b'], tab: 'CSE_SD_Sec_B',       name: 'Software Dev (Sec B)' },
  { keywords: ['software development', 'software dev', 'sd'],        tab: 'CSE_SD_Sec_A',       name: 'Software Dev (Sec A)' },
  { keywords: ['aiml b', 'ai b', 'artificial intelligence b'],       tab: 'CSE_AIML_Sec_B',     name: 'AI & ML (Sec B)' },
  { keywords: ['aiml', 'ai', 'artificial intelligence', 'machine learning', 'ml'], tab: 'CSE_AIML_Sec_A', name: 'AI & ML (Sec A)' },
  { keywords: ['cyber security b', 'cybersec b', 'cyber b', 'cys b'], tab: 'CSE_CyberSec_Sec_B', name: 'Cyber Security (Sec B)' },
  { keywords: ['cyber security', 'cybersec', 'cyber', 'cys'],        tab: 'CSE_CyberSec_Sec_A', name: 'Cyber Security (Sec A)' },
  { keywords: ['ibm'],                                                tab: 'CSE_IBM_Sec_A',      name: 'IBM (Sec A)' },
  { keywords: ['xebia'],                                              tab: 'CSE_Xebia_Sec_A',   name: 'Xebia (Sec A)' },
];

let detectedSection = null;
let detectedSectionName = null;
for (const mapping of sectionMap) {
  if (mapping.keywords.some(k => queryLower.includes(k))) {
    detectedSection = mapping.tab;
    detectedSectionName = mapping.name;
    break;
  }
}

// Day detection
const dayMap = {
  'monday': 'Monday', 'mon': 'Monday',
  'tuesday': 'Tuesday', 'tue': 'Tuesday',
  'wednesday': 'Wednesday', 'wed': 'Wednesday',
  'thursday': 'Thursday', 'thu': 'Thursday',
  'friday': 'Friday', 'fri': 'Friday',
  'saturday': 'Saturday', 'sat': 'Saturday',
};

const now = new Date();
const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const todayWords = ['today', 'aaj'];
const tomorrowWords = ['tomorrow', 'kal'];
let detectedDay = null;

if (todayWords.some(w => queryLower.includes(w))) {
  detectedDay = dayNames[now.getDay()];
} else if (tomorrowWords.some(w => queryLower.includes(w))) {
  const tmp = new Date(now);
  tmp.setDate(tmp.getDate() + 1);
  detectedDay = dayNames[tmp.getDay()];
} else {
  for (const [key, day] of Object.entries(dayMap)) {
    if (queryLower.includes(key)) { detectedDay = day; break; }
  }
}

// Holiday list
const holidays = [
  { date: '2026-01-14', event: 'Makar Sankranti' },
  { date: '2026-01-26', event: 'Republic Day' },
  { date: '2026-02-15', event: 'Maha Shivratri' },
  { date: '2026-03-02', event: 'Holi Break' },
  { date: '2026-03-03', event: 'Holika Dahan' },
  { date: '2026-03-04', event: 'Dhulandi' },
  { date: '2026-03-21', event: 'Eid-Ul-Fitr' },
  { date: '2026-03-26', event: 'Ram Navami' },
  { date: '2026-03-31', event: 'Mahavir Jayanti' },
  { date: '2026-04-14', event: 'Dr. Ambedkar Jayanti' },
  { date: '2026-05-28', event: 'Bakr Id/Eid-Ul-Zuha' },
  { date: '2026-08-15', event: 'Independence Day' },
  { date: '2026-08-28', event: 'Raksha Bandhan' },
  { date: '2026-09-04', event: 'Janmashtami' },
  { date: '2026-10-02', event: 'Mahatma Gandhi Jayanti' },
  { date: '2026-10-20', event: 'Dussehra' },
  { date: '2026-10-29', event: 'Karwa Chauth' },
  { date: '2026-11-06', event: 'Dhanteras' },
  { date: '2026-11-07', event: 'Chhoti Deepawali' },
  { date: '2026-11-08', event: 'Deepawali' },
  { date: '2026-11-09', event: 'Vishwakarma Day/Goverdhan Pooja' },
  { date: '2026-11-10', event: 'Deepawali Break' },
  { date: '2026-11-11', event: 'Bhai Dhooj' },
  { date: '2026-11-24', event: 'Guru Nanak Jayanti' },
  { date: '2026-12-25', event: 'Christmas Day' },
];

// Holiday check — 'today' query
let isHoliday = false;
let holidayEvent = null;
const todayStr = now.toISOString().split('T')[0];
if (todayWords.some(w => queryLower.includes(w))) {
  const h = holidays.find(h => h.date === todayStr);
  if (h) { isHoliday = true; holidayEvent = h.event; }
}

// Holiday check — specific detected day (nearest occurrence this/next week)
if (!isHoliday && detectedDay) {
  const targetDow = dayNames.indexOf(detectedDay);
  const todayDow = now.getDay();
  let diff = targetDow - todayDow;
  if (diff < 0) diff += 7;
  const targetDate = new Date(now);
  targetDate.setDate(now.getDate() + diff);
  const targetDateStr = targetDate.toISOString().split('T')[0];
  const h = holidays.find(h => h.date === targetDateStr);
  if (h) { isHoliday = true; holidayEvent = h.event; }
}

// Range: TabName!A:H — AI node will filter by day
const fullDayRange = detectedSection ? `${detectedSection}!A:H` : null;

return [{
  json: {
    originalQuery: query,
    detectedSection,
    detectedSectionName,
    detectedDay,
    isHoliday,
    holidayEvent,
    needsSection: !detectedSection,
    needsDay: !detectedDay,
    fullDayRange,
    timestamp: new Date().toISOString()
  }
}];

const input = $input.first().json;
return [{
  json: {
    response: `🎉 No classes today — it's ${input.holidayEvent}! Enjoy your day off.`,
    status: 'holiday',
    timestamp: new Date().toISOString()
  }
}];

return [{
  json: {
    response: "I couldn't identify your section. Which section are you in?

Available sections:
• SD (Software Development)
• AIML or AI (Artificial Intelligence & ML)
• CYS or Cyber (Cyber Security)
• IBM
• Xebia

For Sec B, add 'B' — e.g. "SD B" or "Cyber B"

Example: "Monday schedule for SD" or "Today's classes AIML"",
    status: 'missing_section',
    timestamp: new Date().toISOString()
  }
}];

const rows = $input.all().map(i => i.json);
const preprocessed = $('Query Preprocessor').first().json;

const systemInstruction = [
  'You are a timetable assistant for JECRC University, Jaipur.',
  'Format the provided timetable data into a clear, readable schedule.',
  'Use emojis. Be concise. Mark empty slots as Free Period.',
  'Include subject, faculty, and room number when available.',
].join(' ');

const userPrompt = [
  `Student asked: "${preprocessed.originalQuery}"`,
  `Section: ${preprocessed.detectedSectionName}`,
  `Day requested: ${preprocessed.detectedDay || 'Full week'}`,
  '',
  'Timetable data (JSON):',
  JSON.stringify(rows, null, 2),
  '',
  'Format this into a clear, student-friendly schedule.',
].join('\n');

const geminiBody = JSON.stringify({
  system_instruction: { parts: [{ text: systemInstruction }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  generationConfig: { temperature: 0.1, maxOutputTokens: 512 },
});

return [{ json: { geminiBody, preprocessed } }];

const geminiResponse = $input.first().json;
const preprocessed = $('Query Preprocessor').first().json;

let response = '';
try {
  response = geminiResponse.candidates[0].content.parts[0].text || '';
} catch (e) {
  response = 'Sorry, I could not generate a response. Please try again.';
}

if (!response.trim()) {
  response = 'Sorry, I could not retrieve the timetable. Please try again with a specific section and day.';
}

return [{
  json: {
    response,
    status: 'success',
    section: preprocessed.detectedSection,
    day: preprocessed.detectedDay,
    timestamp: new Date().toISOString()
  }
}];
